const presets=[['Klasické','Jednoduché a hladké.',.11],['Elegantné matné','Hladký povrch bez odleskov.',.16],['Lesklé','Lesk po celej ploche.',.16],['Prírodné','Prirodzená štruktúra papiera.',.21],['S lesklým logom','Leskne sa iba vybraný detail.',.27],['Extra hrubé','Výrazne pevnejšie v ruke.',.42]];
const colors=[['Čierna','#292c31'],['Biela','#fff'],['Červená','#bd4145'],['Modrá','#386ca4'],['Zelená','#3d805e'],['Ružová','#d88da4'],['Oranžová','#dd8737'],['Žltá','#e5c34b']];
const defaults={preset:1,view:'gallery',mode:'simple',foil:'none',side:'front',round:false,core:'Červená',qty:250,speed:'RELAX',country:'Slovensko',size:'85 × 55 mm',print:'Obojstranná tlač',price:null};let state={...defaults};try{state={...defaults,...JSON.parse(localStorage.getItem('expresta-prototype')||'{}')}}catch{}if(!presets[state.preset])state={...defaults};let opener;
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('sk-SK',{style:'currency',currency:'EUR'}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function photo(i,modal=false){return `<div class="photo material-photo"><img src="assets/materials-transparent.png" alt="${presets[i][0]} — ukážka povrchu" style="left:${-(i%3)*100}%;top:${i<3?-17.31:-151.92}%"></div>`}
const surfaces=['Bez povrchovej úpravy','Matný, obe strany','Lesklý, obe strany','Prirodzená štruktúra','Matný + lesklý detail','Viacvrstvové prevedenie'];
function parameters(s=state){const foil=s.foil==='none'?'Bez fólie':(s.foil==='gold'?'Zlatá':'Strieborná')+' · '+({front:'vpredu',back:'vzadu',both:'obe strany'}[s.side]);return '<dl class="parameter-grid">'+[['Tlač',s.print==='Jednostranná tlač'?'Jednostranná, farebná':'Obojstranná, farebná'],['Rozmer',s.size],['Povrch',surfaces[s.preset]],['Rohy',s.round?'Zaoblené':'Rovné'],[s.preset===5?'Jadro':'Fólia',s.preset===5?s.core:foil]].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>'}
function tip(i){return i===1?'<span class="tip">Náš tip</span>':''}
function ticketCuts(kind='main',side='vertical'){const modal=kind==='modal',prefix=modal?'modal':'main',fill=modal?'imgVyrez':'imgVyrez',top=modal?'imgVyrezObrys':'imgVyrezObrys1',bottom=modal?'imgVyrezObrys1':'imgVyrezObrys';return '<span class="ticket-cuts '+side+'" aria-hidden="true"><span class="cut first"><img src="assets/'+prefix+'-'+fill+'.svg"><span class="cut-outline"><img src="assets/'+prefix+'-'+top+'.svg"></span></span><span class="cut last"><img src="assets/'+prefix+'-'+fill+'.svg"><span class="cut-outline"><img src="assets/'+prefix+'-'+bottom+'.svg"></span></span></span>'}
function recapCuts(){return '<span class="summary-cut" aria-hidden="true">'+['2','3'].map(n=>'<span><img src="assets/main-imgVyrez1.svg"><span class="outline"><img src="assets/main-imgVyrezObrys'+n+'.svg"></span></span>').join('')+'</span>'} function step(n,label){return '<div class="section-step"><b>'+n+'</b><span>'+label+'</span></div>'}
function gallery(){return `<div class="gallery" role="radiogroup" aria-label="Prevedenie vizitky">${presets.map((p,i)=>`<article class="card ${state.preset===i?'selected':''}"><button class="card-select" data-preset="${i}" role="radio" aria-checked="${state.preset===i}" aria-label="Vybrať ${p[0]}">${photo(i)}${tip(i)}${state.preset===i?'<img class="selected-check" src="assets/redesign/imgVybrane.svg" alt="" aria-hidden="true">':''}<span class="card-body"><strong>${p[0]}</strong><span>${p[1]}</span></span></button><button class="card-expand" data-material-open="${i}" aria-label="Zväčšiť náhľad: ${p[0]}">⤢</button></article>`).join('')}</div>`}
let materialDraft=null;
function draftFor(i){return {...state,preset:i,foil:[3,5].includes(i)?'none':state.foil}}
function renderMaterial(){const i=materialDraft.preset;$('#modal-content').innerHTML=`<h2 id="material-title">Pozrite si prevedenie zblízka</h2><div class="material-layout"><div class="material-carousel" tabindex="0" aria-label="Prevedenia vizitiek" aria-roledescription="carousel">${photo(i,true)}<div class="material-navigation"><button data-material-move="-1" aria-label="Predchádzajúce prevedenie">‹</button><button data-material-move="1" aria-label="Nasledujúce prevedenie">›</button></div></div><div class="material-options" role="radiogroup" aria-label="Prevedenie vizitky"><h4>Prevedenie vizitky</h4>${presets.map((p,j)=>`<button data-material-preset="${j}" class="${i===j?'active':''}" role="radio" aria-checked="${i===j}"><span><b>${p[0]} ${tip(j)}</b><small>${p[1]}</small></span>${i===j?'<span class="tick" aria-hidden="true">✓</span>':''}</button>`).join('')}</div></div><div class="material-parameters"><strong>${presets[i][0]}</strong>${parameters(materialDraft)}</div>${state.foil!=='none'&&materialDraft.foil==='none'?'<p class="material-warning">Toto prevedenie nepodporuje fóliu. Potvrdením sa fólia odstráni.</p>':''}<div class="material-footer"><button class="link" data-action="close">‹ Späť na všetky prevedenia</button><span class="footer-space"></span><button class="secondary material-refine" data-action="material-refine">Doladiť vzhľad</button><button class="primary" data-action="material-apply">Vybrať toto prevedenie</button></div>`}
function openMaterial(i){materialDraft=draftFor(i);opener=document.activeElement;$('#modal').classList.add('material-modal');$('#modal').setAttribute('aria-labelledby','material-title');renderMaterial();$('#modal').showModal();$('.close').focus()}
function moveMaterial(i,focus){materialDraft=draftFor((i+6)%6);renderMaterial();$('#modal-content').querySelector(focus)?.focus()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.materialOpen!==undefined)openMaterial(Number(b.dataset.materialOpen));if(b.dataset.materialPreset!==undefined)moveMaterial(Number(b.dataset.materialPreset),'[data-material-preset="'+b.dataset.materialPreset+'"]');if(b.dataset.materialMove)moveMaterial(materialDraft.preset+Number(b.dataset.materialMove),'[data-material-move="'+b.dataset.materialMove+'"]');if(b.dataset.action==='material-refine'){state={...state,preset:materialDraft.preset,foil:materialDraft.foil,price:null,view:'detail',mode:'simple'};close();render();$('#content .back').focus();$('#calculator').scrollIntoView({block:'start',behavior:'smooth'});return}if(b.dataset.action==='material-apply'){state={...state,preset:materialDraft.preset,foil:materialDraft.foil,price:null};close();render()}});
document.addEventListener('keydown',e=>{if(!materialDraft||!$('#modal').open||!e.target.closest('.material-carousel')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();moveMaterial(materialDraft.preset+(e.key==='ArrowRight'?1:-1),'.material-carousel')});
function discount(qty){return qty>=1000?.5:qty>=500?.25:0}
function quote(qty=state.qty){const rate=presets[state.preset][2]+(state.foil==='none'?0:state.side==='both'?.17:.1)+(state.round?.025:0);return Math.round(((18+qty*rate)*(1-discount(qty))+({RELAX:0,EXPRESS:9.68,'LIGHTNING FAST':32.11}[state.speed]))*100)/100}
function options(items,key,current,extra=''){const icons={foil:['imgFarbaBezFolieVybrana','imgFarbaZlata','imgFarbaStrieborna'],round:['imgRoh','imgRoh1']};return `<div class="choices ${extra}" role="radiogroup" aria-label="${{foil:'Kovový detail',round:'Tvar rohov',side:'Strana fólie',core:'Farba jadra'}[key]}">${items.map(([value,label,color],i)=>`<button class="choice ${current===value?'active':''}" role="radio" aria-checked="${current===value}" data-key="${key}" data-value="${value}">${icons[key]?`<img src="assets/redesign/${icons[key][i]}.svg" alt="">`:color?`<span class="swatch" style="background:${color}"></span>`:''}<span>${label}</span></button>`).join('')}</div>`}
function compatible(){return ![3,5].includes(state.preset)}
function details(){return `<button class="link back" data-action="back">‹ Späť na všetky prevedenia</button>${previewCarousel()}${state.preset===5?`<section class="setting"><h4>Farba jadra <span>${state.core}</span></h4><p>Farba je viditeľná na hrane vizitky.</p>${options(colors.map(([n,c])=>[n,n,c]),'core',state.core,'cores')}</section>`:compatible()?`<section class="setting"><h4>Kovový detail <span>${state.foil==='none'?'Bez fólie':state.foil==='gold'?'Zlatá':'Strieborná'}</span></h4><p>Fólia rozžiari logo alebo vybranú časť grafiky.</p>${options([['none','Bez fólie'],['gold','Zlatá'],['silver','Strieborná']],'foil',state.foil)}${state.foil!=='none'?`<h4 class="sub-label">Umiestnenie fólie</h4>${options([['front','Predná strana'],['back','Zadná strana'],['both','Obe strany']],'side',state.side)}<p>Grafiku pre fóliu pridáte v ďalšom kroku.</p>`:''}</section>`:'<section class="setting"><h4>Prírodný povrch</h4><p>Prirodzená štruktúra papiera bez laminácie.</p></section>'}<section class="setting"><h4>Tvar rohov <span>${state.round?'Zaoblené':'Rovné'}</span></h4>${options([['false','Rovné'],['true','Zaoblené']],'round',String(state.round))}</section>${!compatible()?'<p class="compatibility">Fólia je dostupná na hladkých prevedeniach. <button class="link" data-action="conflict">Pozrieť vhodné prevedenie →</button></p>':''}<button class="link detail-end" data-action="advanced">Otvoriť pokročilé nastavenia ›</button>`}
function select(label,key,values){return `<label><span class="field-label">${label}</span><select data-select="${key}">${values.map(([v,l])=>`<option value="${v}" ${String(state[key])===String(v)?'selected':''}>${l}</option>`).join('')}</select></label>`}
function summaryText(){return [state.preset===5?'Jadro: '+state.core.toLowerCase():state.foil==='none'?'Bez fólie':(state.foil==='gold'?'Zlatá':'Strieborná')+' fólia '+({front:'vpredu',back:'vzadu',both:'na oboch stranách'}[state.side]),state.round?'zaoblené rohy':'rovné rohy'].join(' · ')}
function selectionSummary(){return `<section class="selection-summary"><div class="selection-info"><h2>${presets[state.preset][0]} ${tip(state.preset)}</h2><p>${presets[state.preset][1]}</p>${parameters()}</div><button class="secondary" data-action="detail">Doladiť vzhľad</button></section>`}
const speedOptions=[['RELAX','⛵','Výhodná cena'],['EXPRESS','🚀','Rýchlejšia výroba'],['LIGHTNING FAST','⚡','Najrýchlejšia výroba']];
function countrySelect(){return select('Krajina doručenia','country',['Slovensko','Česko','Rakúsko','Nemecko','Iná krajina'].map(n=>[n,n]))}
function quantityInput(){return `<div class="counter"><button data-action="minus" aria-label="Znížiť počet"><img src="assets/redesign/imgIconMinus.svg" alt=""></button><div class="quantity-value"><input id="quantity" type="number" min="1" max="100000" step="1" value="${state.qty}" aria-describedby="qty-error"><span>ks</span></div><button data-action="plus" aria-label="Zvýšiť počet"><img src="assets/redesign/imgIconPlus.svg" alt=""></button></div><span class="error" id="qty-error" hidden>Zadajte celé číslo od 1 do 100 000.</span>`}
function advanced(){return `<section class="advanced-panel"><h2>Čím viac kópií, tým nižšia cena za 1 ks!</h2><div class="advanced-fields">${select('Rozmer a ohyb','size',[['85 × 55 mm','85 × 55 mm'],['90 × 50 mm','90 × 50 mm']])}${select('Materiál','preset',presets.map((p,i)=>[i,p[0]]))}<button class="advanced-extra" data-action="detail"><span>Extra možnosti</span><b>${summaryText()}</b></button>${select('Tlač','print',[['Obojstranná tlač','Obojstranná'],['Jednostranná tlač','Jednostranná']])}<div><label for="quantity">Počet kópií</label>${quantityInput()}</div><div class="advanced-price"><span>Cena s DPH</span><strong>${money(quote())}</strong><small>(${money(quote()/state.qty)} / ks)</small></div></div><div class="advanced-bottom"><p>🟢 Potrebujete poradiť? <a href="mailto:info@expresta.sk">info@expresta.sk</a><br><a href="tel:+421232113070">02 / 3211 3070</a> · Radi vám poradíme.</p>${select('Rýchlosť výroby','speed',speedOptions.map(([n])=>[n,n]))}${countrySelect()}<button class="primary" data-action="upload">Návrh a objednávka ›</button></div></section>`}
function render(){localStorage.setItem('expresta-prototype',JSON.stringify(state));document.querySelectorAll('.tabs button').forEach(b=>{const active=b.dataset.action===state.mode;b.classList.toggle('active',active);b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});$('#view-title').hidden=true;$('#intro').hidden=true;const advancedMode=state.mode==='advanced';$('.layout').className='layout '+(advancedMode?'advanced-layout':state.view==='detail'?'detail-layout':'gallery-layout');$('#content').innerHTML=advancedMode?advanced():state.view==='detail'?details():gallery();$('#summary').hidden=advancedMode;$('#summary').innerHTML=advancedMode?'':`${selectionSummary()}<section class="summary-section quantity-section"><label class="label" for="quantity">Počet kusov</label>${quantityInput()}<div class="quick" role="radiogroup" aria-label="Počet kusov">${[100,250,500,1000].map(n=>`<button class="${state.qty===n?'active':''}" role="radio" aria-checked="${state.qty===n}" data-key="qty" data-value="${n}"><span>${n.toLocaleString('sk-SK')} ks ${discount(n)?`<small>−${discount(n)*100} %</small>`:''}</span>${state.qty===n?'<span class="tick" aria-hidden="true">✓</span>':''}</button>`).join('')}</div></section><section class="summary-section speeds"><h4>Rýchlosť výroby</h4><div role="radiogroup" aria-label="Rýchlosť výroby">${speedOptions.map(([n,icon,d])=>`<button class="speed ${state.speed===n?'active':''}" role="radio" aria-checked="${state.speed===n}" data-key="speed" data-value="${n}"><span><b><span aria-hidden="true">${icon}</span> ${n}</b><small>${d}</small></span>${state.speed===n?'<span class="tick" aria-hidden="true">✓</span>':n!=='RELAX'?`<span class="speed-extra">+${money(n==='EXPRESS'?9.68:32.11)}</span>`:''}</button>`).join('')}</div><p>Výroba začína po schválení grafiky a úhrade.</p></section><section class="summary-section shipping">${countrySelect()}<button class="delivery-link" data-action="delivery"><span class="truck" aria-hidden="true"><img src="assets/redesign/imgIconDelivery.svg" alt=""></span><span>Pozrieť kuriérov<br>a časy dodania</span><span class="delivery-chevron" aria-hidden="true"><img src="assets/redesign/imgDeliveryChevron.svg" alt=""></span></button></section><section class="summary-section summary-cta">${state.price!==null?priceResult():`<button class="primary" data-action="calculate">Vypočítať cenu <img src="assets/redesign/imgIconCalculatorOrigami.svg" alt=""></button>`}</section><p class="help">Neviete si vybrať? Radi vám poradíme.</p>`;}

function priceResult(){return `<div class="calculated-price" role="status" aria-label="Výsledok výpočtu">${discount(state.qty)?`<span class="discount-badge">Zľava ${discount(state.qty)*100} %</span>`:''}<div class="price-label-row"><span>Cena s DPH</span>${discount(state.qty)?`<s>${money((state.price-({RELAX:0,EXPRESS:9.68,'LIGHTNING FAST':32.11}[state.speed]))/(1-discount(state.qty))+({RELAX:0,EXPRESS:9.68,'LIGHTNING FAST':32.11}[state.speed]))}</s>`:''}</div><div class="price-values"><strong>${money(state.price)}</strong><small>${money(state.price/state.qty)} / ks</small></div></div><button class="primary upload-cta" data-action="upload">Nahrať grafiku <img src="assets/main-imgIconCalculatorOrigami.svg" alt=""></button>`}
function update(key,value){state[key]=key==='round'?value==='true':['qty','preset'].includes(key)?Number(value):value;state.price=null;render()}
function choose(i){if([3,5].includes(i)&&state.foil!=='none'){show(`<h2>Zmena prevedenia odstráni fóliu</h2><p>Prevedenie ${presets[i][0]} nepodporuje fóliu. Počet kusov, rozmer, tlač a rýchlosť výroby zostanú.</p><div class="modal-actions"><button class="primary" data-confirm-preset="${i}">Zmeniť prevedenie</button><button class="secondary" data-action="close">Ponechať výber</button></div>`);return}update('preset',i)}
function show(html){$('#modal').classList.remove('material-modal');$('#modal').removeAttribute('aria-labelledby');materialDraft=null;opener=document.activeElement;$('#modal-content').innerHTML=html;$('#modal').showModal();$('.close').focus()}
function close(){ $('#modal').close();materialDraft=null;$('#modal').classList.remove('material-modal');$('#modal').removeAttribute('aria-labelledby');opener?.focus() }
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.preset!==undefined){choose(Number(b.dataset.preset));return}if(b.dataset.confirmPreset!==undefined){state.foil='none';close();update('preset',b.dataset.confirmPreset);return}if(b.dataset.key){update(b.dataset.key,b.dataset.value);return}switch(b.dataset.action){case'simple':state.mode='simple';render();break;case'advanced':state.mode='advanced';render();break;case'detail':state.mode='simple';state.view='detail';render();break;case'back':state.view='gallery';render();break;case'minus':update('qty',Math.max(1,state.qty-50));break;case'plus':update('qty',Math.min(100000,state.qty+50));break;case'reset':state={...defaults};render();break;case'close':close();break;case'upload':if($('#quantity')&&(!Number.isInteger(Number($('#quantity').value))||Number($('#quantity').value)<1||Number($('#quantity').value)>100000)){$('#qty-error').hidden=false;$('#quantity').focus();break}show(`<h2>Nahrať grafiku</h2><p>V ďalšom kroku sem zákazník pridá grafiku pre svoje vizitky.</p><p class="small">Toto je ukážka prechodu v prototype. Súbory sa zatiaľ nenahrávajú ani neodosielajú.</p><button class="primary" data-action="close">Späť na kalkuláciu</button>`);break;case'calculate':{const n=Number($('#quantity').value);if(!Number.isInteger(n)||n<1||n>100000){$('#qty-error').hidden=false;$('#quantity').setAttribute('aria-invalid','true');$('#quantity').focus();return}state.qty=n;state.price=quote(n);render();break}case'conflict':show(`<h2>Fólia potrebuje iné prevedenie</h2><p>Prepneme na Elegantné matné so zlatou fóliou. Farebné jadro sa odstráni; rozmer, tlač, počet kusov a rýchlosť výroby zostanú.</p><p><b>${presets[state.preset][0]} → Elegantné matné / zlatá fólia</b></p><div class="modal-actions"><button class="primary" data-action="accept">Zmeniť na matné s fóliou</button><button class="secondary" data-action="close">Ponechať výber</button></div>`);break;case'accept':close();state.preset=1;state.foil='gold';state.view='detail';state.price=null;render();break;case'delivery':show(`<h2>Dodanie a kuriéri</h2><b>Krajina doručenia: ${esc(state.country)}</b>${state.country==='Slovensko'?`<p>Orientačný prehľad dopravy</p>${[['Výdajné miesto SPS','1 deň · od 1,99 €'],['Výdajné miesto DPD','1 deň · od 4,49 €'],['Kuriér','1 deň · od 4,99 €'],['DHL Express','1 deň · od 14,49 €'],['Mestský kuriér Bratislava','2 hodiny · od 12,18 €'],['Osobný odber — Squarebizz Bory','Po dokončení výroby · zadarmo']].map(([n,d])=>`<div class="delivery-row"><b>${n}</b><p>${d}</p></div>`).join('')}<p class="tiny">Nadrozmerná doprava: DHL od 60,49 € · Geis od 39,99 €</p>`:'<div class="notice">Pre túto krajinu prototyp nemá cenník dopravy. V živej kalkulačke sa dostupní kuriéri a ceny načítajú podľa krajiny a zásielky.</div>'}<p class="small">Čas prepravy sa pripočítava k času výroby. Konkrétny spôsob doručenia si vyberiete v košíku.</p><p class="tiny">Orientačné údaje z návrhu. Prototyp neoveruje aktuálne ceny ani dostupnosť.</p>`);break}});
document.addEventListener('change',e=>{if(e.target.dataset.select){const key=e.target.dataset.select;if(key==='preset')choose(Number(e.target.value));else update(key,e.target.value)}});$('#modal').addEventListener('cancel',e=>{e.preventDefault();close()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close()});render();

document.querySelector('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();state.mode=e.key==='Home'?'simple':e.key==='End'?'advanced':state.mode==='simple'?'advanced':'simple';render();document.querySelector('.tabs button.active').focus()});

document.addEventListener('input',e=>{if(e.target.id!=='quantity')return;const n=Number(e.target.value),valid=Number.isInteger(n)&&n>=1&&n<=100000;$('#qty-error').hidden=valid;e.target.setAttribute('aria-invalid',String(!valid));if(!valid)return;const hadPrice=state.price!==null;state.qty=n;state.price=null;localStorage.setItem('expresta-prototype',JSON.stringify(state));document.querySelectorAll('.quick button').forEach(b=>{const active=Number(b.dataset.value)===n;b.classList.toggle('active',active);b.setAttribute('aria-checked',String(active));b.querySelector('.tick')?.remove();if(active)b.insertAdjacentHTML('beforeend','<span class="tick" aria-hidden="true">✓</span>')});if(hadPrice&&$('.summary-cta'))$('.summary-cta').innerHTML='<button class="primary" data-action="calculate">Vypočítať cenu <img src="assets/redesign/imgIconCalculatorOrigami.svg" alt=""></button>';if($('.advanced-price'))$('.advanced-price').innerHTML='<span>Cena s DPH</span><strong>'+money(quote())+'</strong><small>('+money(quote()/state.qty)+' / ks)</small>'});
